builder.Services.AddAuthentication(JwtBearerDefaults.AuthenticationScheme)
    .AddJwtBearer(options =>
    {
        options.Authority = "https://login.example.com";
        options.Audience = "orders-api";
    });
builder.Services.AddAuthorization(options =>
{
    options.FallbackPolicy = new AuthorizationPolicyBuilder()
        .RequireAuthenticatedUser()
        .Build(); // entire API requires login unless [AllowAnonymous]
});

var app = builder.Build();
app.UseRouting();
app.UseAuthentication(); // sets HttpContext.User
app.UseAuthorization();  // checks policies
app.MapControllers();

[ApiController]
[Route("api/orders")]
public class OrdersController : ControllerBase
{
    [HttpGet("{id}")]
    [Authorize] // no token → 401; token ok → continues
    public IActionResult Get(int id) => Ok(/* ... */);

    [HttpDelete("{id}")]
    [Authorize(Policy = "CanDeleteOrder")] // token ok but no claim → 403
    public IActionResult Delete(int id) => NoContent();

    [HttpGet("public-stats")]
    [AllowAnonymous] // skips authorization requirement
    public IActionResult Stats() => Ok(/* ... */);
}

[HttpPut("{id}")]
[Authorize]
public async Task<IActionResult> Update(int id, OrderDto dto)
{
    var order = await _db.Orders.FindAsync(id);
    if (order is null) return NotFound();

    var userId = User.FindFirstValue(ClaimTypes.NameIdentifier);
    if (order.OwnerId != userId && !User.IsInRole("Admin"))
        return Forbid(); // 403 — authenticated but not owner

    // update...
    return NoContent();
}

app.Use(async (context, next) =>
{
    await next();
    if (context.Response.StatusCode is 401 or 403)
    {
        var log = context.RequestServices.GetRequiredService<ILoggerFactory>()
            .CreateLogger("AuthDiag");
        var authed = context.User.Identity?.IsAuthenticated ?? false;
        log.LogWarning("{Status} Path={Path} Authenticated={Authed}",
            context.Response.StatusCode, context.Request.Path, authed);
        // 401 + Authenticated=false → missing/invalid token
        // 403 + Authenticated=true → policy or Forbid()
    }
});
